module TopModule (
    input clk,
    input areset,
    input train_valid,
    input train_taken,
    output reg [1:0] state
);

    always @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= 2'b01;
        end else if (train_valid) begin
            if (train_taken) begin
                if (state != 2'd3)
                    state <= state + 2'd1;
            end else begin
                if (state != 2'd0)
                    state <= state - 2'd1;
            end
        end
    end

endmodule
